/** Full default FASTQ workflow design. Every biological sample, library and contrast is explicit. */
final class NfcoreRnasplice104Request {
    private NfcoreRnasplice104Request() { }
    // Deliberately mirrors the original search expression, including its permissive alternative.
    private static final Pattern SOURCE_CONDITION=Pattern.compile("^(([A-Za-z]|[.][._A-Za-z])[._A-Za-z0-9]*)|[.]$");
    record Library(String first,String second) {boolean singleEnd(){return second==null;}}
    record Sample(String id,String condition,String strandedness,List<Library> libraries){Sample{libraries=List.copyOf(libraries);}}
    record Contrast(String id,String treatment,String control) {String rmatsPrefix(){return treatment+"-"+control;}}
    record Pair(String treatment,String control) { }
    record Request(String source,String plugins,String engine,String containerHome,String imageSet,String fasta,String gtf,
                   List<Sample> samples,List<Contrast> contrasts,int executorCpus,long executorMemory,
                   int taskCpus,long taskMemory,long taskSeconds,int misoReadLength,List<String> misoPlotGenes,int rmatsReadLength,
                   boolean rmatsPairedStatistics,Map<String,List<Pair>> rmatsPairings,int rmatsMaximumRows,int quantificationMaximumRows,Map<?,?> limits,
                   String rmatsMaximumP,String rmatsMinimumPsi,Map<?,?> raw){Request{samples=List.copyOf(samples);contrasts=List.copyOf(contrasts);misoPlotGenes=List.copyOf(misoPlotGenes);rmatsPairings=Map.copyOf(rmatsPairings);}}
    static Request read(Path source)throws IOException{return parse(object(NextflowParameters.parse(utf8(bytes(source,4194304)),4194304,100000)));}
    static Request parse(Map<?,?> raw)throws IOException {
        keys(raw,"schema_version","pipeline_profile","engine_profile","source_directory","plugins_directory","engine_directory","container_home","image_set","fasta","gtf","samples","contrasts","executor_cpus","executor_memory_bytes","task_cpus","task_memory_bytes","task_seconds","miso_read_length","miso_plot_genes","rmats_read_length","rmats_paired_statistics","rmats_pairings","rmats_maximum_rows","quantification_maximum_rows","limits","rmats_maximum_p","rmats_minimum_absolute_psi");integer(raw.get("schema_version"),1,1);
        if(!NfcoreRnasplice104Profile.ID.equals(raw.get("pipeline_profile")))throw new NextflowProcess.Unavailable("This full RNA adapter requires explicit original rnasplice1.0.4; select the reported source edition or retain the skipped analysis");
        if(!NfcoreValidationPlugin.ENGINE.equals(raw.get("engine_profile")))throw new NextflowProcess.Unavailable("Select the exact qualified Nextflow24.04.4 engine explicitly; no author engine edition is inferred or substituted");
        int executorCpus=(int)integer(raw.get("executor_cpus"),1,1024),taskCpus=(int)integer(raw.get("task_cpus"),1,1024);long executorMemory=integer(raw.get("executor_memory_bytes"),16777216,1099511627776L),taskMemory=integer(raw.get("task_memory_bytes"),16777216,1099511627776L);if(taskCpus>executorCpus||taskMemory>executorMemory)throw new IOException("Source task maxima exceed the explicit local executor capacity");
        var samples=new ArrayList<Sample>();var identities=new HashSet<String>();var conditions=new LinkedHashMap<String,HashSet<String>>();int libraries=0;
        for(Object item:list(raw.get("samples"))){Map<?,?> row=object(item);keys(row,"id","condition","strandedness","libraries");String id=literal(row.get("id"),"biological sample"),condition=condition(row.get("condition")),strand=text(row.get("strandedness"));if(!identities.add(id))throw new IOException("Repeated biological sample object; declare its technical libraries under that sample: "+id);if(!Set.of("unstranded","forward","reverse").contains(strand))throw new IOException("Unknown literal source strandedness: "+strand);var runs=new ArrayList<Library>();var firstReads=new HashSet<String>();Boolean single=null;
            for(Object entry:list(row.get("libraries"))){Map<?,?> pair=object(entry);keys(pair,"fastq_1","fastq_2");String first=path(pair.get("fastq_1"));String secondValue=text(pair.get("fastq_2"));String second=secondValue.isEmpty()?null:path(secondValue);fastq(first);if(second!=null){fastq(second);if(!suffixes(first).equals(suffixes(second)))throw new IOException("Original FASTQ pair suffixes differ; no filename repair is inferred for "+id);}if(!firstReads.add(first))throw new IOException("Original source requires each sample/first-FASTQ pair to be unique: "+id);boolean isSingle=second==null;if(single!=null&&single!=isSingle)throw new IOException("Mixed single/paired technical libraries cannot form one unambiguous biological sample: "+id);single=isSingle;String technical=id+"_T"+(runs.size()+1);if(!technical.replaceFirst("_T[0-9]+","").equals(id))throw new IOException("Original first-match technical-suffix grouping would change/split biological sample "+id+" at technical run "+(runs.size()+1)+". No scientific identifier is repaired.");runs.add(new Library(first,second));libraries=Math.addExact(libraries,1);}
            if(runs.isEmpty()||libraries>100000)throw new IOException("Require nonempty technical libraries within the complete100000-row capacity");samples.add(new Sample(id,condition,strand,runs));conditions.computeIfAbsent(condition,key->new HashSet<>()).add(id);
        }
        if(samples.size()<4||samples.size()>100000||conditions.size()<2)throw new IOException("Full differential-splicing workflow requires at least two conditions with biological replicates");for(var group:conditions.entrySet())if(group.getValue().size()<2)throw new IOException("Insufficient distinct biological replicates for "+group.getKey()+"; technical libraries do not count as independent replicates. The original checker consumes its reader before this check; no model/replicate substitution is admitted.");
        var contrasts=new ArrayList<Contrast>();var contrastIds=new HashSet<String>();var rmatsPrefixes=new HashSet<String>();for(Object item:list(raw.get("contrasts"))){Map<?,?> row=object(item);keys(row,"id","treatment","control");String id=literal(row.get("id"),"contrast"),treatment=condition(row.get("treatment")),control=condition(row.get("control"));if(!contrastIds.add(id)||treatment.equals(control)||!conditions.containsKey(treatment)||!conditions.containsKey(control))throw new IOException("Duplicate contrast ID, self contrast or absent source condition: "+id);var contrast=new Contrast(id,treatment,control);if(!rmatsPrefixes.add(contrast.rmatsPrefix()))throw new IOException("Original rMATS publication prefixes collide despite contrast IDs: "+contrast.rmatsPrefix()+". No contrast merge/rename is inferred.");contrasts.add(contrast);}if(contrasts.isEmpty()||contrasts.size()>100000)throw new IOException("Declare the complete nonempty contrast population within capacity");
        var protocols=new LinkedHashMap<String,HashSet<String>>();for(var sample:samples)protocols.computeIfAbsent(sample.condition(),key->new HashSet<>()).add(sample.libraries().get(0).singleEnd()+"/"+sample.strandedness());for(var contrast:contrasts){var combined=new HashSet<>(protocols.get(contrast.treatment()));combined.addAll(protocols.get(contrast.control()));if(combined.size()!=1)throw new NextflowProcess.Unavailable("Original rMATS selects one read-layout/strand flag from the first treatment metadata for "+contrast.id()+"; this profile cannot validate mixed protocols in that comparison. Analysis skipped; use a workflow/model representing all libraries without subsetting or metadata replacement.");}
        String p=text(raw.get("rmats_maximum_p")),psi=text(raw.get("rmats_minimum_absolute_psi"));if(p.length()>128||psi.length()>128||!p.equals(p.strip())||!psi.equals(psi.strip()))throw new IOException("Invalid explicit post-fit decimal threshold tokens");try{new RmatsResults.Threshold(new BigDecimal(p),new BigDecimal(psi));}catch(IllegalArgumentException failure){throw new IOException("Invalid explicit post-fit thresholds",failure);}
        List<String> genes=strings(raw.get("miso_plot_genes"));if(genes.isEmpty()||genes.size()>100000||new HashSet<>(genes).size()!=genes.size())throw new IOException("Declare the exact nonempty MISO plot-gene population without duplicate IDs");for(String gene:genes){if(gene.isEmpty()||gene.indexOf(',')>=0||gene.chars().anyMatch(c->c<32||c==127)||!gene.equals(gene.strip()))throw new IOException("Original comma-separated MISO plot genes cannot represent this literal ID; no identifier repair is inferred");shellToken(gene,"MISO gene",false);}
        if(!(raw.get("rmats_paired_statistics")instanceof Boolean paired))throw new IOException("Declare the statistical paired-model choice explicitly; paired FASTQs do not establish biological pairing");Map<?,?> suppliedPairs=object(raw.get("rmats_pairings"));var pairings=new LinkedHashMap<String,List<Pair>>();if(!paired&&!suppliedPairs.isEmpty()||paired&&!suppliedPairs.keySet().equals(contrastIds))throw new IOException("Declare all contrast-specific biological pairs for paired statistics, or an empty pairing map for unpaired statistics");
        for(var contrast:contrasts)if(paired){var pairs=new ArrayList<Pair>();var firsts=new HashSet<String>();var seconds=new HashSet<String>();for(Object entry:list(suppliedPairs.get(contrast.id()))){Map<?,?> pair=object(entry);keys(pair,"treatment","control");String first=text(pair.get("treatment")),second=text(pair.get("control"));if(!conditions.get(contrast.treatment()).contains(first)||!conditions.get(contrast.control()).contains(second)||!firsts.add(first)||!seconds.add(second))throw new IOException("Invalid/repeated biological pairing for "+contrast.id());pairs.add(new Pair(first,second));}if(!firsts.equals(conditions.get(contrast.treatment()))||!seconds.equals(conditions.get(contrast.control())))throw new IOException("Incomplete biological pairing for "+contrast.id());pairings.put(contrast.id(),List.copyOf(pairs));}
        return new Request(path(raw.get("source_directory")),path(raw.get("plugins_directory")),path(raw.get("engine_directory")),path(raw.get("container_home")),path(raw.get("image_set")),path(raw.get("fasta")),path(raw.get("gtf")),samples,contrasts,executorCpus,executorMemory,taskCpus,taskMemory,integer(raw.get("task_seconds"),1,604800),(int)integer(raw.get("miso_read_length"),1,1000000),List.copyOf(genes),(int)integer(raw.get("rmats_read_length"),1,1000000),paired,pairings,(int)integer(raw.get("rmats_maximum_rows"),0,10000000),(int)integer(raw.get("quantification_maximum_rows"),0,10000000),object(raw.get("limits")),p,psi,raw);
    }
    /** POSIX producer paths stay strings so portable verification retains case and separators. */
    static String path(Object raw)throws IOException {String path=text(raw);if(!path.startsWith("/")||path.endsWith("/")||path.indexOf('\\')>=0||path.chars().anyMatch(c->c<32||c==127))throw new IOException("Declare literal normalized absolute Linux producer paths");for(String part:path.substring(1).split("/",-1))if(part.isEmpty()||part.equals(".")||part.equals(".."))throw new IOException("No empty/dot/parent producer path members are allowed");return path;}
    private static String literal(Object raw,String field)throws IOException {String value=text(raw);if(value.isEmpty()||value.indexOf(' ')>=0||value.indexOf(',')>=0||value.indexOf('/')>=0||value.indexOf('\\')>=0||value.equals(".")||value.equals("..")||value.chars().anyMatch(c->c<32||c==127))throw new IOException("Original source would change or cannot represent this "+field+" identifier in its literal paths/BAM lists. No scientific ID is repaired: "+value);shellToken(value,field,false);return value;}
    private static String condition(Object raw)throws IOException {String value=text(raw);if(value.isEmpty()||value.indexOf('/')>=0||value.indexOf('\\')>=0||value.chars().anyMatch(c->c<32||c==127)||!SOURCE_CONDITION.matcher(value).find())throw new IOException("Original source rejects this condition label or it cannot remain within literal owned paths: "+value);shellToken(value,"condition",true);return value;}
    private static void fastq(String value)throws IOException {String name=value.substring(value.lastIndexOf('/')+1);if(!List.of(".fastq.gz",".fq.gz").stream().anyMatch(name::endsWith))throw new IOException("The locked original checker requires .fastq.gz or .fq.gz. Its usage documentation also mentions uncompressed input; that discrepancy is retained. No compression or filename repair is inferred: "+value);shellToken(name,"FASTQ basename",false);}
    private static void shellToken(String value,String field,boolean spaces)throws IOException{if(value.codePoints().anyMatch(c->!Character.isLetterOrDigit(c)&&"_.-+:=@%".indexOf(c)<0&&!(spaces&&c==' ')))throw new NextflowProcess.Unavailable("Original source interpolates this "+field+" into shell commands; its literal characters exceed the adapter's representable token scope. Analysis skipped without identifier/filename repair; use a workflow supporting the unchanged identifier: "+value);}
    // Python pathlib's final two basename suffixes are used by the locked original checker.
    private static List<String> suffixes(String path){String name=path.substring(path.lastIndexOf('/')+1);int first=0;while(first<name.length()&&name.charAt(first)=='.')first++;name=name.substring(first);if(name.endsWith("."))return List.of();var result=new ArrayList<String>();for(int at=name.indexOf('.');at>=0;){int next=name.indexOf('.',at+1);result.add(name.substring(at,next<0?name.length():next));at=next;}return result.subList(Math.max(0,result.size()-2),result.size());}
    static String csv(String value){return value.indexOf(',')>=0||value.indexOf('"')>=0||value.indexOf('\r')>=0||value.indexOf('\n')>=0?'"'+value.replace("\"","\"\"")+'"':value;}
}
